#!/usr/bin/env python3
"""Regenerate the committed M10 test font fixtures: self-authored minimal TTFs.

Only Python's standard library is used. Run from anywhere:

    python3 tests/fixtures/fonts/generate_variants.py

The script overwrites `toy_test_bold.ttf`, `toy_test_italic.ttf` and `toy_cjk.ttf`
next to itself; the M8b `toy_test.ttf` is generated by generate_toy_test.py and
left untouched. Output is deterministic for a given Python version. The committed
README documents the designs and metrics the tests rely on; keep it and the tests
in sync when changing the generator.

It generates three new fixtures (the existing toy_test.ttf is left untouched):
- toy_test_bold.ttf    same "Toy Test Font" family, Bold subfamily, weight 700,
                       wider advance so metrics prove the bold face was selected
- toy_test_italic.ttf  same family, Italic subfamily, weight 400, italic metadata
                       (outlines are not sheared: metadata only, documented)
- toy_cjk.ttf          "Toy CJK" family with a few synthetic Han glyphs, used to
                       test per-character coverage fallback / Chinese text

Design (all our own work, same approach as the M8b fixture):
- unitsPerEm 1000, ascender 800, descender -200, lineGap 0
- monospace; glyph shapes come from a hand-authored 5x7 block grid
- deliberately tiny charsets; every other code point maps to .notdef
"""

import pathlib
import struct
from pathlib import Path

UNITS_PER_EM = 1000
ASCENDER = 800
DESCENDER = -200
LINE_GAP = 0
LSB = 50
CELL = 100
GRID_COLS = 5
GRID_ROWS = 7

NOTDEF = [
    "#####",
    "#...#",
    "#...#",
    "#...#",
    "#...#",
    "#...#",
    "#####",
]

LATIN_GLYPHS = {
    " ": [".....", ".....", ".....", ".....", ".....", ".....", "....."],
    ".": [".....", ".....", ".....", ".....", ".....", ".##..", ".##.."],
    "0": [".###.", "#...#", "#..##", "#.#.#", "##..#", "#...#", ".###."],
    "1": ["..#..", ".##..", "..#..", "..#..", "..#..", "..#..", ".###."],
    "2": [".###.", "#...#", "....#", "...#.", "..#..", ".#...", "#####"],
    "?": [".###.", "#...#", "....#", "...#.", "..#..", ".....", "..#.."],
    "A": [".###.", "#...#", "#...#", "#####", "#...#", "#...#", "#...#"],
    "B": ["####.", "#...#", "#...#", "####.", "#...#", "#...#", "####."],
    "C": [".####", "#....", "#....", "#....", "#....", "#....", ".####"],
    "a": [".....", ".....", ".###.", "....#", ".####", "#...#", ".####"],
    "b": ["#....", "#....", "####.", "#...#", "#...#", "#...#", "####."],
    "c": [".....", ".....", ".####", "#....", "#....", "#...#", ".###."],
}

# Synthetic placeholder shapes for a few Han code points: enough to prove
# coverage-based fallback and to render deterministic Chinese fixture pages. They
# are intentionally simple block-art, not real glyph designs.
CJK_GLYPHS = {
    "\u4e2d": ["#####", "..#..", "..#..", "#####", "..#..", "..#..", "..#.."],  # 中
    "\u6587": ["..#..", "#####", "#...#", "..#..", "..#..", ".#.#.", "#...#"],  # 文
    "\u4f60": ["#....", "#.#..", "#.#..", "#.#..", "#.#..", "#.#..", "#.#.."],  # 你
    "\u597d": [".#...", ".#####", ".#..#", ".#..#", ".#..#", ".#..#", ".#..#"],  # 好
    "\u7f51": ["#####", "#...#", "#.#.#", "#.#.#", "#...#", "#####", "....."],  # 网
}


def glyph_contours(pattern):
    contours = []
    for row, line in enumerate(pattern):
        col = 0
        while col < GRID_COLS:
            if line[col] != "#":
                col += 1
                continue
            start = col
            while col < GRID_COLS and line[col] == "#":
                col += 1
            x0 = LSB + start * CELL
            x1 = LSB + col * CELL
            y0 = (GRID_ROWS - 1 - row) * CELL
            y1 = (GRID_ROWS - row) * CELL
            contours.append([(x0, y0), (x0, y1), (x1, y1), (x1, y0)])
    return contours


def build_glyf_and_loca(spec):
    glyph_patterns = [NOTDEF] + [spec["glyphs"][chr(cp)] for cp in spec["codepoints"]]
    glyf = bytearray()
    loca = [0]
    for pattern in glyph_patterns:
        contours = glyph_contours(pattern)
        start = len(glyf)
        if not contours:
            loca.append(start)
            continue
        points = [point for contour in contours for point in contour]
        xs = [p[0] for p in points]
        ys = [p[1] for p in points]
        data = struct.pack(">hhhhh", len(contours), min(xs), min(ys), max(xs), max(ys))
        end = -1
        for contour in contours:
            end += len(contour)
            data += struct.pack(">H", end)
        data += struct.pack(">H", 0)  # instructionLength
        data += bytes([1] * len(points))  # all points on-curve, 16-bit deltas
        previous = 0
        for x, _ in points:
            data += struct.pack(">h", x - previous)
            previous = x
        previous = 0
        for _, y in points:
            data += struct.pack(">h", y - previous)
            previous = y
        glyf += data
        while len(glyf) % 4:
            glyf += b"\x00"
        loca.append(len(glyf))
    loca_data = b"".join(struct.pack(">I", offset) for offset in loca)
    return bytes(glyf), loca_data, glyph_patterns


def build_cmap(spec):
    mapping = [(cp, gid) for gid, cp in enumerate(spec["codepoints"], start=1)]
    mapping.sort()
    segments = []
    index = 0
    while index < len(mapping):
        start_cp, start_gid = mapping[index]
        end_cp, end_gid = start_cp, start_gid
        index += 1
        while index < len(mapping):
            cp, gid = mapping[index]
            if cp == end_cp + 1 and gid == end_gid + 1:
                end_cp, end_gid = cp, gid
                index += 1
            else:
                break
        segments.append((start_cp, end_cp, (start_gid - start_cp) & 0xFFFF))
    segments.append((0xFFFF, 0xFFFF, 1))

    seg_count = len(segments)
    entry_selector = max(0, seg_count.bit_length() - 1)
    search_range = 2 * (1 << entry_selector)
    range_shift = 2 * seg_count - search_range
    subtable = struct.pack(
        ">HHHHHHH", 4, 16 + 8 * seg_count, 0, 2 * seg_count, search_range, entry_selector,
        range_shift)
    subtable += b"".join(struct.pack(">H", end) for _, end, _ in segments)
    subtable += struct.pack(">H", 0)
    subtable += b"".join(struct.pack(">H", start) for start, _, _ in segments)
    subtable += b"".join(struct.pack(">H", delta) for _, _, delta in segments)
    subtable += b"".join(struct.pack(">H", 0) for _ in segments)

    header = struct.pack(">HH", 0, 1)
    encoding = struct.pack(">HHI", 3, 1, 12)
    return header + encoding + subtable


def build_name(spec):
    strings = {
        1: spec["family"],
        2: spec["subfamily"],
        3: spec["fullname"] + "; " + spec["subfamily"] + "; generated by toy-browser",
        4: spec["fullname"],
        6: spec["postscript"],
    }
    storage = bytearray()
    records = []
    for name_id in sorted(strings):
        encoded = strings[name_id].encode("utf-16-be")
        records.append((3, 1, 0x409, name_id, len(encoded), len(storage)))
        storage += encoded
    header = struct.pack(">HHH", 0, len(records), 6 + 12 * len(records))
    entries = b"".join(
        struct.pack(">HHHHHH", platform, encoding, language, name_id, length, offset)
        for platform, encoding, language, name_id, length, offset in records
    )
    return header + entries + bytes(storage)


def build_head(spec):
    timestamp = 3_500_000_000
    return struct.pack(
        ">IIIIHHqqhhhhHHhhh",
        0x00010000, 0x00010000, 0, 0x5F0F3CF5, 0x0001, UNITS_PER_EM, timestamp, timestamp,
        LSB, 0, LSB + GRID_COLS * CELL, GRID_ROWS * CELL,
        spec["mac_style"], 8, 2, 1, 0)


def build_hhea(spec):
    advance = spec["advance"]
    max_x = LSB + GRID_COLS * CELL
    return struct.pack(
        ">IhhhH" + "h" * 11 + "H",
        0x00010000, ASCENDER, DESCENDER, LINE_GAP, advance, LSB, advance - max_x, max_x,
        1, 0, 0, 0, 0, 0, 0, 0, len(spec["glyphs"]) + 1)


def build_maxp(num_glyphs, max_points, max_contours):
    return struct.pack(
        ">IHHHHHHHHHHHHHH", 0x00010000, num_glyphs, max_points, max_contours, 0, 0, 2, 0, 0, 0,
        0, 0, 0, 0, 0)


def build_os2(spec):
    advance = spec["advance"]
    data = bytearray()
    data += struct.pack(">HhHHH", 4, advance, spec["weight"], 5, 0)
    data += struct.pack(">hhhh", 650, 600, 0, 75)
    data += struct.pack(">hhhh", 650, 600, 0, 350)
    data += struct.pack(">hh", 50, 300)
    data += struct.pack(">h", 0)  # sFamilyClass
    data += bytes([2, 0, 0, 0, 0, 0, 0, 0, 0, 0])  # panose: Latin text
    data += struct.pack(">IIII", *spec["unicode_ranges"])
    data += b"TOY "
    first, last = spec["codepoints"][0], spec["codepoints"][-1]
    data += struct.pack(">HH", spec["fs_selection"], first)
    data += struct.pack(">H", last)
    data += struct.pack(">hhh", ASCENDER, DESCENDER, LINE_GAP)
    data += struct.pack(">HH", ASCENDER, -DESCENDER)
    data += struct.pack(">II", *spec["codepage_ranges"])
    data += struct.pack(">hh", 500, 700)
    data += struct.pack(">HHH", 0, spec["codepoints"][0], 1)
    assert len(data) == 96, len(data)
    return bytes(data)


def build_post(spec):
    angle_fixed = int(round(spec["italic_angle"] * 65536))
    return struct.pack(
        ">IihhIIIII",
        0x00030000,
        angle_fixed,
        -100,
        50,
        1,
        0,
        0,
        0,
        0,
    )


def build_hmtx(spec):
    return b"".join(
        struct.pack(">Hh", spec["advance"], LSB) for _ in range(len(spec["glyphs"]) + 1))


def table_checksum(data):
    padded = data + b"\x00" * ((4 - len(data) % 4) % 4)
    return sum(struct.unpack(">%dI" % (len(padded) // 4), padded)) & 0xFFFFFFFF


def generate(spec):
    glyf_data, loca_data, glyph_patterns = build_glyf_and_loca(spec)
    num_glyphs = len(glyph_patterns)
    max_points = max(
        sum(len(contour) for contour in glyph_contours(pattern)) for pattern in glyph_patterns)
    max_contours = max(len(glyph_contours(pattern)) for pattern in glyph_patterns)
    tables = {
        "head": build_head(spec),
        "hhea": build_hhea(spec),
        "maxp": build_maxp(num_glyphs, max_points, max_contours),
        "hmtx": build_hmtx(spec),
        "cmap": build_cmap(spec),
        "loca": loca_data,
        "glyf": glyf_data,
        "name": build_name(spec),
        "OS/2": build_os2(spec),
        "post": build_post(spec),
    }
    tags = sorted(tables)
    num_tables = len(tags)
    entry_selector = max(0, num_tables.bit_length() - 1)
    search_range = 16 * (1 << entry_selector)
    header = struct.pack(
        ">IHHHH", 0x00010000, num_tables, search_range, entry_selector,
        16 * num_tables - search_range)
    offset = 12 + 16 * num_tables
    directory = bytearray()
    payload = bytearray()
    head_offset = None
    for tag in tags:
        data = tables[tag]
        directory += struct.pack(">4sIII", tag.encode("latin-1"), table_checksum(data), offset,
                                 len(data))
        if tag == "head":
            head_offset = offset
        payload += data
        while len(payload) % 4:
            payload += b"\x00"
        offset = 12 + 16 * num_tables + len(payload)
    font = bytearray(header + directory + payload)
    whole = sum(struct.unpack(">%dI" % (len(font) // 4), bytes(font))) & 0xFFFFFFFF
    adjustment = (0xB1B0AFBA - whole) & 0xFFFFFFFF
    struct.pack_into(">I", font, head_offset + 8, adjustment)
    out = Path(spec["out"])
    out.write_bytes(bytes(font))
    print(f"wrote {out} ({len(font)} bytes, {num_glyphs} glyphs, {len(spec['codepoints'])} cps)")


def spec(out, family, subfamily, postscript, advance, weight, fs_selection, mac_style,
         italic_angle, glyphs, unicode_ranges, codepage_ranges):
    codepoints = sorted(ord(c) for c in glyphs)
    return {
        "out": out,
        "family": family,
        "subfamily": subfamily,
        "fullname": family + " " + subfamily,
        "postscript": postscript,
        "advance": advance,
        "weight": weight,
        "fs_selection": fs_selection,
        "mac_style": mac_style,
        "italic_angle": italic_angle,
        "glyphs": glyphs,
        "codepoints": codepoints,
        "unicode_ranges": unicode_ranges,
        "codepage_ranges": codepage_ranges,
    }


LATIN_RANGES = (1, 0, 0, 0)
LATIN_CODEPAGES = (1, 0)
CJK_RANGES = (0, (1 << 27) | (1 << 16) | (1 << 29), 0, 0)
CJK_CODEPAGES = (1 << 18, 0)

HERE = pathlib.Path(__file__).resolve().parent

SPECS = [
    spec(HERE / "toy_test_bold.ttf", "Toy Test Font", "Bold", "ToyTestFont-Bold",
         650, 700, 0x20, 1, 0, LATIN_GLYPHS, LATIN_RANGES, LATIN_CODEPAGES),
    spec(HERE / "toy_test_italic.ttf", "Toy Test Font", "Italic",
         "ToyTestFont-Italic", 620, 400, 0x01, 2, -120, LATIN_GLYPHS, LATIN_RANGES,
         LATIN_CODEPAGES),
    spec(HERE / "toy_cjk.ttf", "Toy CJK", "Regular", "ToyCJK-Regular", 700, 400,
         0x40, 0, 0, CJK_GLYPHS, CJK_RANGES, CJK_CODEPAGES),
]


def main():
    for item in SPECS:
        pathlib.Path(item["out"]).parent.mkdir(parents=True, exist_ok=True)
        generate(item)


if __name__ == "__main__":
    main()
